fn remove_kth_element(list: &Vec<i32>, k: usize) -> Vec<i32> {
    // k is 1-based, so convert to 0-based indexing for Rust slices
    let zero_based_k = k - 1;
    let n = list.len();

    // Take prefix: elements before k-th (exclusive)
    let prefix = &list[0..zero_based_k];

    // Take suffix: elements after k-th (from k to end)
    let suffix = &list[k..n];

    // Concatenate prefix and suffix into new vector
    // Using `to_vec` clones the slices into a new vector
    let mut new_list = Vec::with_capacity(n - 1);
    new_list.extend_from_slice(prefix);
    new_list.extend_from_slice(suffix);

    new_list
}